def feature(ctx):
    o = ctx["observed"]; T, N = o.shape
    idx = np.where(o, np.arange(T)[:, None], -1)
    last = np.maximum.accumulate(idx, axis=0)
    gap = np.where(last < 0, T, np.arange(T)[:, None] - last)
    return np.log1p(np.minimum(gap, 2000)).astype(np.float32)

def feature(ctx):
    r = ctx["rain_mm"].astype(np.float64); T = len(r)
    c = np.r_[0.0, np.cumsum(r)]
    s = np.arange(1, T + 1); lo = np.maximum(s - 12, 0)
    return np.log1p((c[s] - c[lo]) / 4).astype(np.float32)

def feature(ctx):
    raw = ctx["raw"]; T, N = raw.shape; W = ctx["WEEK"]
    c = np.vstack([np.zeros((1, N)), np.cumsum(raw, axis=0, dtype=np.float64)])
    s = np.arange(1, T + 1)
    def win(a, b):
        lo = np.clip(s - b, 0, T); hi = np.clip(s - a, 0, T)
        return (c[hi] - c[lo]) / np.maximum(hi - lo, 1)[:, None]
    out = np.log((win(0, W) + 10) / (win(W, 5 * W) + 10)); out[: 5 * W] = 0
    return out.astype(np.float32)
